// Transaction Filter Component
// Filters transactions by date range, type, and category
// Filtering is done client-side on the already-fetched transactions
// to avoid stale state and race conditions

import React, { useState, useEffect, useMemo } from 'react';
import axios from 'axios';
import './TransactionFilter.css';

function TransactionFilter({ onFilterChange, transactions = [] }) {
  const [dateFilter, setDateFilter]     = useState('');
  const [typeFilter, setTypeFilter]     = useState('');
  const [categoryFilter, setCategoryFilter] = useState('');

  const token = localStorage.getItem('token');

  // Derive unique categories from the transactions prop (no extra API call needed)
  const categories = useMemo(() => {
    const set = new Set(transactions.map(t => t.category).filter(Boolean));
    return [...set].sort();
  }, [transactions]);

  // Apply filters whenever filter state or source transactions change
  useEffect(() => {
    applyFilters();
  // eslint-disable-next-line
  }, [dateFilter, typeFilter, categoryFilter, transactions]);

  const getDateBounds = (filter) => {
    const now = new Date();
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());

    if (filter === 'daily') {
      const tomorrow = new Date(today); tomorrow.setDate(today.getDate() + 1);
      return { start: today, end: tomorrow };
    }
    if (filter === 'weekly') {
      const start = new Date(today); start.setDate(today.getDate() - 6);
      const end   = new Date(today); end.setDate(today.getDate() + 1);
      return { start, end };
    }
    if (filter === 'monthly') {
      const start = new Date(now.getFullYear(), now.getMonth(), 1);
      const end   = new Date(now.getFullYear(), now.getMonth() + 1, 1);
      return { start, end };
    }
    if (filter === 'yearly') {
      const start = new Date(now.getFullYear(), 0, 1);
      const end   = new Date(now.getFullYear() + 1, 0, 1);
      return { start, end };
    }
    return null;
  };

  const applyFilters = () => {
    // No filters active → show everything
    if (!dateFilter && !typeFilter && !categoryFilter) {
      onFilterChange(null);
      return;
    }

    let result = [...transactions];

    // Date filter
    if (dateFilter) {
      const bounds = getDateBounds(dateFilter);
      if (bounds) {
        result = result.filter(t => {
          // t.date is "YYYY-MM-DD" string
          const d = new Date(t.date + 'T00:00:00');
          return d >= bounds.start && d < bounds.end;
        });
      }
    }

    // Type filter
    if (typeFilter) {
      result = result.filter(t => t.type === typeFilter);
    }

    // Category filter
    if (categoryFilter) {
      result = result.filter(t =>
        t.category?.trim().toLowerCase() === categoryFilter.trim().toLowerCase()
      );
    }

    onFilterChange(result);
  };

  const handleReset = () => {
    setDateFilter('');
    setTypeFilter('');
    setCategoryFilter('');
    // useEffect will fire and call onFilterChange(null)
  };

  const hasActiveFilter = dateFilter || typeFilter || categoryFilter;

  return (
    <div className="transaction-filter">
      <h3>🔍 Filter Transactions</h3>

      <div className="filter-controls">
        {/* Date Filter */}
        <div className="filter-group">
          <label>📅 Date Range</label>
          <select
            value={dateFilter}
            onChange={(e) => setDateFilter(e.target.value)}
            className="filter-select"
          >
            <option value="">All Time</option>
            <option value="daily">Today</option>
            <option value="weekly">Last 7 Days</option>
            <option value="monthly">This Month</option>
            <option value="yearly">This Year</option>
          </select>
        </div>

        {/* Type Filter */}
        <div className="filter-group">
          <label>💳 Transaction Type</label>
          <select
            value={typeFilter}
            onChange={(e) => setTypeFilter(e.target.value)}
            className="filter-select"
          >
            <option value="">All Types</option>
            <option value="income">Income</option>
            <option value="expense">Expense</option>
          </select>
        </div>

        {/* Category Filter */}
        <div className="filter-group">
          <label>🏷️ Category</label>
          <select
            value={categoryFilter}
            onChange={(e) => setCategoryFilter(e.target.value)}
            className="filter-select"
          >
            <option value="">All Categories</option>
            {categories.map((cat) => (
              <option key={cat} value={cat}>{cat}</option>
            ))}
          </select>
        </div>

        {/* Reset Button */}
        <button
          onClick={handleReset}
          className="filter-reset-btn"
          disabled={!hasActiveFilter}
        >
          🔄 Reset Filters
        </button>
      </div>

      {/* Active filters display */}
      {hasActiveFilter && (
        <div className="active-filters">
          <p>
            <strong>Active:</strong>
            {dateFilter    && <span className="filter-tag">{dateFilter}</span>}
            {typeFilter    && <span className="filter-tag">{typeFilter}</span>}
            {categoryFilter && <span className="filter-tag">{categoryFilter}</span>}
          </p>
        </div>
      )}
    </div>
  );
}

export default TransactionFilter;
